const raw = $input.first().json;
const body = raw.body ?? raw;
const msg = body.whatsappInboundMessage || body;

const fromNumber = msg.from;
const userId = msg.fromUserId || msg.from;
const name = (msg.customerProfile && msg.customerProfile.name) || '';
const displayPhone = msg.to;
const wabaId = msg.wabaId;
const messageId = msg.id || msg.wamid;
const text = (msg.text && msg.text.body) || '';
const ts = msg.sendTime ? Math.floor(new Date(msg.sendTime).getTime()/1000).toString() : Math.floor(Date.now()/1000).toString();

return [{
    json: {
          messaging_product: 'whatsapp',
          metadata: {
                  display_phone_number: displayPhone,
                  phone_number_id: wabaId
          },
          contacts: [
            {
                      profile: { name: name },
                      wa_id: fromNumber,
                      user_id: userId
            }
                ],
          messages: [
            {
                      from: fromNumber,
                      from_user_id: userId,
                      id: messageId,
                      timestamp: ts,
                      text: { body: text }
            }
                ]
    }
}];

const raw = $('Received_msg').first().json.messages[0].from;
const codes = ['3406', '341'];
let to = raw;
return [{
    json: {
          to,
          text_body: $('AI Agent').first().json.output
    }
}];

const body = $input.first().json.body;

// SOLO procesar mensajes del inbox nuevo "Tienda" (id 2).
// Esto evita el eco/bucle: el mirror legacy (CW Log Incoming/Outgoing) escribe
// copias en el inbox viejo (id 1), y como el webhook de Chatwoot es a nivel de
// cuenta (dispara para TODOS los inboxes), esas copias volverian a entrar aca
// y relanzarian el bot indefinidamente si no se filtran.
if (!body.inbox || body.inbox.id !== 2) {
  return [];
}

// Ignorar notas privadas
if (body.private === true) {
  return [];
}

// Solo procesar mensajes entrantes de contactos (ignorar los salientes/eco del propio bot)
if (body.message_type !== 'incoming') {
  return [];
}

const sender = body.sender || {};
const phone = (sender.phone_number || '').replace('+', '');

return [{
  json: {
    messaging_product: "whatsapp",
    metadata: {
      display_phone_number: phone,
      phone_number_id: body.inbox.id
    },
    contacts: [{
      profile: { name: sender.name || phone },
      wa_id: phone,
      user_id: phone
    }],
    messages: [{
      from: phone,
      from_user_id: phone,
      id: body.id,
      timestamp: String(Math.floor(Date.now()/1000)),
      text: { body: body.content || '' }
    }],
    chatwoot: {
      conversation_id: body.conversation ? body.conversation.id : null,
      inbox_id: body.inbox.id,
      account_id: body.account ? body.account.id : null
    }
  }
}];

let canal = 'ycloud';
try {
  const test = $('Received_msg (Chatwoot)').first();
  if (test) canal = 'chatwoot';
} catch (e) {
  canal = 'ycloud';
}
return [{ json: { canal } }];

const conv = $('Received_msg (Chatwoot)').first().json.chatwoot;
return [{
    json: {
          conversation_id: conv.conversation_id,
          text_body: $('AI Agent').first().json.output
    }
}];
